package br.com.conectatea.conexao.domain; import br.com.conectatea.shared.domain.AuditableEntity; import jakarta.persistence.*; @Entity @Table(name="conexoes_profissionais") public class ConexaoProfissional extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="solicitante_id") private Long solicitanteId; @Column(name="destinatario_id") private Long destinatarioId; @Column(name="par_menor_id") private Long parMenorId; @Column(name="par_maior_id") private Long parMaiorId; @Enumerated(EnumType.STRING) private StatusConexao status=StatusConexao.PENDENTE; protected ConexaoProfissional(){} public ConexaoProfissional(Long a,Long b){solicitanteId=a;destinatarioId=b;parMenorId=Math.min(a,b);parMaiorId=Math.max(a,b);} public Long getId(){return id;} public Long getSolicitanteId(){return solicitanteId;} public Long getDestinatarioId(){return destinatarioId;} public StatusConexao getStatus(){return status;} public void respond(Long actor,StatusConexao s){if(!destinatarioId.equals(actor))throw new org.springframework.security.access.AccessDeniedException("Somente destinatário responde");status=s;} public boolean participant(Long p){return solicitanteId.equals(p)||destinatarioId.equals(p);} }
